INSERT OR REPLACE INTO sources (id,title,publisher,author,url,published_at,accessed_at,source_type,supports,notes) VALUES ('S-24','人工智能前沿与创新-三张活地图讲义-一-课程大作业.md','本项目仓库（课程讲义整理稿）','课程组 / 小组整理','file:///D:/桌面/大作业/人工智能前沿与创新-三张活地图讲义-一-课程大作业.md','2026-10-17','2026-11-01','project_doc','["大作业要求：三张地图（领域/生态/认知）通过同一交互式网站呈现，中期起云端公开访问","课程明确要求的认知方法：系统观（局部与整体、瓶颈）、发展观（方法出现背景、条件变化）","课程列举的六种分析方法：问题定义、系统拆解、对照比较、演进分析、多目标取舍、反例与边界检查；要求选 2–3 种给出本组实际例子","课程要求的六类成长习惯：思维、学习、实践、管理、认识更新、协作","理解程度标注三档：已初步理解、已经尝试、待深入学习","课程关联五档：前置基础、核心覆盖、部分涉及、实践应用、自主拓展","关系词表需说明「采用/依赖/资助/付费/合作/竞争」等具体关系，未证实联系标注为推断","AI 回答不能作为事实证据；自动获取信息需核实后进入正式地图；每周至少检查一次","访问要求：云端运行、国内普通网络可访问、无需安装软件、无需逐人申请权限、不索取个人模型密钥","现场展示 8 分钟结构：选题 1 分钟、三图 3 分钟、AI 能力 2 分钟、认识变化 1 分钟、未知与后续 1 分钟"]','一手项目资料（课程讲义整理稿），本地文件，无公开 URL。整理日期 2026-10-17。');
INSERT OR REPLACE INTO sources (id,title,publisher,author,url,published_at,accessed_at,source_type,supports,notes) VALUES ('S-25','附件.培养方案(1).docx —— 2026级人工智能专业培养方案','项目附件（学校培养方案节选）','未署名（学校教务文件）','file:///D:/桌面/大作业/附件.培养方案(1).docx',NULL,'2026-11-01','curriculum','["培养目标三条（面向 AI 基础理论/核心算法/智能系统与行业应用；毕业时能力；毕业五年左右发展）","毕业要求共 10 条，原文条目包括：1 数理基础与科学思维；2 计算基础与系统实现；3 人工智能核心理论与方法；4 智能系统设计与工程实现；5 交叉应用；6 科研训练与探究；7 协作沟通与项目推进；8 负责任人工智能与科技伦理；9 国际视野与跨文化交流；10 前沿追踪与终身学习","毕业要求 3 明确列出「机器学习、深度学习、表示学习、推理规划、生成模型、感知与多模态处理、决策与智能体」","毕业要求 4 明确列出「数据获取与处理、模型构建、训练评估、系统集成、部署优化和持续迭代」","毕业要求 6 明确列出「文献检索、问题分析、实验设计、结果解释和学术表达」","毕业要求 8 明确列出「安全性、公平性、透明性、隐私保护、知识产权、可解释性和社会影响」"]','一手项目资料（本地 docx，Apache POI 生成，dc:creator=Apache POI，创建时间 2026-10-17T09:20:02Z）。重要限制：该附件只包含「培养目标」与「毕业要求」，不含课程目录、学分表或教学进程表，因此所有具体课名均无法从该文件核实。');
INSERT OR REPLACE INTO sources (id,title,publisher,author,url,published_at,accessed_at,source_type,supports,notes) VALUES ('S-26','三张活地图-项目完整方案-V2.0-一步到位版.md','本项目仓库','项目方案文档','file:///D:/桌面/大作业/三张活地图-项目完整方案-V2.0-一步到位版.md',NULL,'2026-11-01','project_doc','["数据模型要求（nodes / relations / sources / update_log / feedback / candidate_content 六实体及字段）","证据四级状态：已核实、部分核实、推断、待核实","快变量 4 周复核规则","受控关系词表（solves / based_on / implemented_by / requires_knowledge / alternative_to / complements / evaluated_by / 提出 / 采用 / 依赖 / 改进 / 质疑 / taught_in / enables_practice / 资助 / 付费 / 提供 / 定价 / 合作 / 竞争 / 孵化 / 开源）","三图联动透视镜与动态溯源引擎的交互规格、移动端降级与 X-Ray 开关要求","AI 能力必须与地图数据集成、无命中时不得编造","评测集 10–20 题及必须评估的维度"]','项目内部规格文档（一手）。本地文件。');
