INSERT OR REPLACE INTO relations (id,source_node_id,target_node_id,relation_type,coverage,description,reasoning_chain,source_ids,evidence_status,checked_at) VALUES ('R-063','D-T-LANGCHAIN','D-R-RETRIEVAL','alternative_to',NULL,'LangChain 与本项目自建轻量检索是两种可选实现；本项目因管线单一、需可逐行解释而选择自建。',NULL,'["S-26","S-32"]','已核实','2026-11-01');
