INSERT OR REPLACE INTO relations (id,source_node_id,target_node_id,relation_type,coverage,description,reasoning_chain,source_ids,evidence_status,checked_at) VALUES ('R-065','D-T-LANGCHAIN','D-T-LLAMAINDEX','alternative_to',NULL,'两者分工不同：LlamaIndex 聚焦数据索引与检索，LangChain 聚焦模型与工具编排，实践中常组合使用。','LangChain 官方定位为 agent engineering platform（编排）-> LlamaIndex 官方定位为数据框架（索引与检索）-> 两者解决的问题层次不同 -> 因此是互补而非同质替代关系。','["S-32","S-33"]','推断','2026-11-01');
