INSERT OR REPLACE INTO relations (id,source_node_id,target_node_id,relation_type,coverage,description,reasoning_chain,source_ids,evidence_status,checked_at) VALUES ('R-067','E-OR-ZHIPU','E-COM-HF','开源',NULL,'智谱将 GLM-4.6 的测试题目与 Agent 轨迹数据集公开托管在 Hugging Face（zai-org/CC-Bench-trajectories），使厂商自评可被第三方检验。',NULL,'["S-16","S-36"]','已核实','2026-11-01');
INSERT OR REPLACE INTO relations (id,source_node_id,target_node_id,relation_type,coverage,description,reasoning_chain,source_ids,evidence_status,checked_at) VALUES ('R-068','D-M-GLM46','D-T-HF','evaluated_by',NULL,'GLM-4.6 的官方评测轨迹数据集托管在 HF，为其能力自评提供了可验证入口。',NULL,'["S-16","S-36"]','已核实','2026-11-01');
INSERT OR REPLACE INTO relations (id,source_node_id,target_node_id,relation_type,coverage,description,reasoning_chain,source_ids,evidence_status,checked_at) VALUES ('R-069','E-COM-VLLM','E-OR-ZHIPU','alternative_to',NULL,'自建 vLLM 推理服务与购买 MaaS 是两条对立路线：前者成本前置为 GPU 与运维，后者按调用量线性付费。','MaaS 按 token 计费且无需运维 -> 自建 vLLM 需一次性 GPU 与持续运维投入 -> 调用量越大自建单位成本越低 -> 因此二者构成替代关系，临界点取决于实际 QPS（本项目无 GPU 条件，未实测临界值）。','["S-15","S-34"]','推断','2026-11-01');
INSERT OR REPLACE INTO relations (id,source_node_id,target_node_id,relation_type,coverage,description,reasoning_chain,source_ids,evidence_status,checked_at) VALUES ('R-070','E-COM-OLLAMA','E-OR-DEEPSEEK','alternative_to',NULL,'本地运行开源模型与调用云端 API 是两条对立路线：前者零 API 费用、数据不出机，后者能力更强、无需硬件。','云端 API 按 token 付费且能力为旗舰水平 -> 本地运行需自有硬件且模型能力受限于可下载的开源权重 -> 对数据敏感或高频调用场景本地更划算 -> 因此构成替代关系。','["S-17","S-35"]','推断','2026-11-01');
INSERT OR REPLACE INTO relations (id,source_node_id,target_node_id,relation_type,coverage,description,reasoning_chain,source_ids,evidence_status,checked_at) VALUES ('R-071','D-T-OLLAMA','D-T-ZHIPU','alternative_to',NULL,'本地模型运行时与云端 MaaS API 互为替代；本项目因无 GPU 未部署本地模型，改用非生成式检索直出作为离线降级。',NULL,'["S-26","S-35"]','已核实','2026-11-01');
INSERT OR REPLACE INTO relations (id,source_node_id,target_node_id,relation_type,coverage,description,reasoning_chain,source_ids,evidence_status,checked_at) VALUES ('R-072','D-T-VLLM','D-T-ZHIPU','alternative_to',NULL,'自建推理引擎与云端 MaaS 互为替代，代表成本结构的两种极端。',NULL,'["S-15","S-34"]','已核实','2026-11-01');
