INSERT OR REPLACE INTO relations (id,source_node_id,target_node_id,relation_type,coverage,description,reasoning_chain,source_ids,evidence_status,checked_at) VALUES ('R-087','E-PA-RAG','E-OR-ZHIPU','采用',NULL,'智谱提供的模型能力（200K–1M 上下文、Function Calling、知识库服务）以 RAG 类应用为主要落地形态之一。','RAG 成为知识密集型应用的主流方法 -> 模型厂商需要提供长上下文与工具调用能力以支撑 RAG -> 智谱在官方文档中提供知识库服务与上下文缓存等配套能力 -> 因此可认为厂商采用了该方法路线（厂商未逐条声明采用 RAG 论文，故标推断）。','["S-15","S-16"]','推断','2026-11-01');
