INSERT OR REPLACE INTO relations (id,source_node_id,target_node_id,relation_type,coverage,description,reasoning_chain,source_ids,evidence_status,checked_at) VALUES ('R-099','E-US-STUDENTS','E-APP-THREEMAPS','付费',NULL,'选课同学不为本应用付费（课程作业、免费公开访问）；其「支付」形式是注意力与反馈。','本应用为课程作业且要求无需申请权限即可浏览 -> 使用者不产生直接货币支付 -> 但同学通过互评与反馈投入注意力并提供内容改进线索 -> 因此在广义上构成对应用的价值回报（非货币）。','["S-24","S-26"]','推断','2026-11-01');
