INSERT OR REPLACE INTO relations (id,source_node_id,target_node_id,relation_type,coverage,description,reasoning_chain,source_ids,evidence_status,checked_at) VALUES ('R-102','E-US-TEAM','E-APP-THREEMAPS','采用',NULL,'本小组成员是应用的建设者与维护者，承担内容核实、技术选型与后续更新责任。',NULL,'["S-24","S-26"]','已核实','2026-11-01');
