INSERT OR REPLACE INTO relations (id,source_node_id,target_node_id,relation_type,coverage,description,reasoning_chain,source_ids,evidence_status,checked_at) VALUES ('R-107','E-OR-ZHIPU','E-COST-TOKEN','定价',NULL,'智谱以「元/百万 Tokens」为单位定价，并区分输入、输出、缓存命中与缓存存储四项费用。',NULL,'["S-15"]','已核实','2026-11-01');
INSERT OR REPLACE INTO relations (id,source_node_id,target_node_id,relation_type,coverage,description,reasoning_chain,source_ids,evidence_status,checked_at) VALUES ('R-108','E-OR-DEEPSEEK','E-COST-PEAK','定价',NULL,'DeepSeek 对同一模型按高峰/空闲时段收取不同价格（空闲为高峰一半），用价格信号引导削峰。',NULL,'["S-17"]','已核实','2026-11-01');
INSERT OR REPLACE INTO relations (id,source_node_id,target_node_id,relation_type,coverage,description,reasoning_chain,source_ids,evidence_status,checked_at) VALUES ('R-109','E-OR-DEEPSEEK','E-COST-ADDON','定价',NULL,'DeepSeek 的 Search / Fetch 按每 1,000 次成功请求 5 元单独计费，且原免费场景自 2026-11-01 00:00 起转为收费。',NULL,'["S-17"]','已核实','2026-11-01');
INSERT OR REPLACE INTO relations (id,source_node_id,target_node_id,relation_type,coverage,description,reasoning_chain,source_ids,evidence_status,checked_at) VALUES ('R-110','E-OR-ZHIPU','E-COST-ADDON','定价',NULL,'智谱定价页把模型推理、搜索工具服务、知识库服务分列计费，知识库服务另有独立计费说明。',NULL,'["S-15"]','已核实','2026-11-01');
INSERT OR REPLACE INTO relations (id,source_node_id,target_node_id,relation_type,coverage,description,reasoning_chain,source_ids,evidence_status,checked_at) VALUES ('R-111','E-OR-ZHIPU','E-COST-FREE','定价',NULL,'智谱对 GLM-4.7-Flash 等模型标注「免费」、多数模型的缓存存储标注「限时免费」，属市场推广性定价策略。','厂商提供免费档模型 -> 免费档仍需承担推理算力成本 -> 其动机是扩大开发者生态并向付费档转化 -> 「限时免费」措辞保留随时收费权利 -> 因此免费档成本由厂商的市场推广预算承担。','["S-15"]','推断','2026-11-01');
INSERT OR REPLACE INTO relations (id,source_node_id,target_node_id,relation_type,coverage,description,reasoning_chain,source_ids,evidence_status,checked_at) VALUES ('R-112','E-COST-FREE','E-COST-INFRA','solves',NULL,'免费档模型使学生项目能以近零模型成本运行，把应用侧成本压缩到基础设施与人力两项。',NULL,'["S-15","S-26"]','已核实','2026-11-01');
INSERT OR REPLACE INTO relations (id,source_node_id,target_node_id,relation_type,coverage,description,reasoning_chain,source_ids,evidence_status,checked_at) VALUES ('R-113','E-COST-TRAIN','D-M-GLM46','依赖',NULL,'GLM-4.6 的总参 355B / 激活 32B（MoE 结构）反映训练成本规模，也说明激活参数少是降低推理成本的关键手段。','官方披露总参 355B、激活 32B -> 总参规模决定训练算力投入 -> 激活参数远小于总参说明采用混合专家结构 -> 单次推理只激活部分参数 -> 因此推理成本低于同总参稠密模型（官方未公布训练成本金额，此处不推测）。','["S-16"]','推断','2026-11-01');
INSERT OR REPLACE INTO relations (id,source_node_id,target_node_id,relation_type,coverage,description,reasoning_chain,source_ids,evidence_status,checked_at) VALUES ('R-114','E-OR-ZHIPU','E-COST-TRAIN','付费',NULL,'模型提供方承担训练与推理算力的前置成本，通过 API 定价与订阅回收。','厂商投入芯片、电力与研发完成模型训练 -> 该成本无法由使用者直接支付 -> 厂商通过按 token 计费与订阅回收 -> 因此厂商是训练成本的承担者（官方未公布具体金额）。','["S-15","S-16"]','推断','2026-11-01');
INSERT OR REPLACE INTO relations (id,source_node_id,target_node_id,relation_type,coverage,description,reasoning_chain,source_ids,evidence_status,checked_at) VALUES ('R-115','E-OR-DEEPSEEK','E-COST-TRAIN','付费',NULL,'DeepSeek 同样承担模型训练成本，并通过双时段定价与缓存折扣回收。','厂商完成模型训练与部署 -> 通过高峰/空闲双价与缓存命中折扣调节负载并回收成本 -> 因此厂商是训练成本承担者（官方未公布具体金额）。','["S-17","S-20"]','推断','2026-11-01');
INSERT OR REPLACE INTO relations (id,source_node_id,target_node_id,relation_type,coverage,description,reasoning_chain,source_ids,evidence_status,checked_at) VALUES ('R-116','E-COM-VLLM','E-COST-INFRA','付费',NULL,'自建推理路线把成本从「按调用付费」转为「GPU 与运维人力前置投入」。','自建 vLLM 需购置或租用 GPU -> 需持续投入运维与调优人力 -> 成本不随调用量线性增长而是前置固定 -> 因此该路线的承担者是应用方或自建方（本项目无 GPU 条件，未实测临界点）。','["S-34"]','推断','2026-11-01');
INSERT OR REPLACE INTO relations (id,source_node_id,target_node_id,relation_type,coverage,description,reasoning_chain,source_ids,evidence_status,checked_at) VALUES ('R-117','E-US-TEAM','E-COST-INFRA','付费',NULL,'本组承担应用侧基础设施与运维成本；通过零依赖选型（node:sqlite 单文件、静态前端）把它压到最低。',NULL,'["S-26","S-27"]','已核实','2026-11-01');
INSERT OR REPLACE INTO relations (id,source_node_id,target_node_id,relation_type,coverage,description,reasoning_chain,source_ids,evidence_status,checked_at) VALUES ('R-118','E-US-TEAM','E-COST-TOKEN','付费',NULL,'本组承担模型调用的 token 成本；因选用免费档主渠道，实际金额极低，本次交付无可查询账单（尚未采集）。',NULL,'["S-15","S-43"]','部分核实','2026-11-01');
INSERT OR REPLACE INTO relations (id,source_node_id,target_node_id,relation_type,coverage,description,reasoning_chain,source_ids,evidence_status,checked_at) VALUES ('R-119','E-COST-INFRA','E-COST-TOKEN','complements',NULL,'应用侧成本由基础设施与模型调用两部分构成，二者相互独立且需分别核算。',NULL,'["S-26","S-27"]','已核实','2026-11-01');
INSERT OR REPLACE INTO relations (id,source_node_id,target_node_id,relation_type,coverage,description,reasoning_chain,source_ids,evidence_status,checked_at) VALUES ('R-120','E-COST-ADDON','E-COST-TOKEN','质疑',NULL,'附加能力单独计价使「成本 = 单价 x token 数」的估算方式失效，成本结构比想象中复杂。','传统估算只考虑 token 单价与用量 -> Search/Fetch 等能力按请求次数单独计费 -> 且原免费场景会转为收费 -> 因此仅按 token 估算会低估实际成本（本项目据此坚持自建检索以避免不可预期的附加计费）。','["S-17"]','推断','2026-11-01');
INSERT OR REPLACE INTO relations (id,source_node_id,target_node_id,relation_type,coverage,description,reasoning_chain,source_ids,evidence_status,checked_at) VALUES ('R-121','E-DIM-UPSTREAM','E-PA-RAG','based_on',NULL,'五段产业链条的第一段以 RAG 等学术方法为起点，说明学术成果是产业应用的上游输入。',NULL,'["S-01","S-24"]','已核实','2026-11-01');
INSERT OR REPLACE INTO relations (id,source_node_id,target_node_id,relation_type,coverage,description,reasoning_chain,source_ids,evidence_status,checked_at) VALUES ('R-122','E-DIM-UPSTREAM','E-APP-THREEMAPS','complements',NULL,'本组应用位于五段链条的第四段，是把学术方法与商用能力转化为大一学生可用工具的环节。',NULL,'["S-24","S-26"]','已核实','2026-11-01');
INSERT OR REPLACE INTO relations (id,source_node_id,target_node_id,relation_type,coverage,description,reasoning_chain,source_ids,evidence_status,checked_at) VALUES ('R-123','E-DIM-COMPETE','D-T-DSAPI','based_on',NULL,'OpenAI 兼容接口成为事实标准，使渠道可互换，是应用方获得容灾与议价能力的技术前提。',NULL,'["S-17","S-18"]','已核实','2026-11-01');
INSERT OR REPLACE INTO relations (id,source_node_id,target_node_id,relation_type,coverage,description,reasoning_chain,source_ids,evidence_status,checked_at) VALUES ('R-124','E-DIM-COMPETE','E-OR-ZHIPU','竞争',NULL,'智谱与 DeepSeek 在低价/免费档与旗舰档两个层面竞争；接口兼容使应用方可随时切换。','两家厂商均提供 OpenAI 兼容接口 -> 应用方切换成本主要在配置层 -> 免费档（GLM-4.7-Flash）与低价档（deepseek-flash）面向同一批开发者 -> 因此构成直接竞争关系（厂商未声明竞争关系，故标推断）。','["S-15","S-17","S-18"]','推断','2026-11-01');
INSERT OR REPLACE INTO relations (id,source_node_id,target_node_id,relation_type,coverage,description,reasoning_chain,source_ids,evidence_status,checked_at) VALUES ('R-125','E-DIM-COMPETE','E-OR-DEEPSEEK','竞争',NULL,'DeepSeek 的双时段定价与缓存折扣是价格竞争的具体手段，直接影响应用方的调用策略。','DeepSeek 用空闲时段半价与缓存命中低价吸引批量调用 -> 智谱用免费档吸引开发者 -> 两者争夺同一批应用开发者 -> 因此构成价格层面的竞争（推断）。','["S-17"]','推断','2026-11-01');
INSERT OR REPLACE INTO relations (id,source_node_id,target_node_id,relation_type,coverage,description,reasoning_chain,source_ids,evidence_status,checked_at) VALUES ('R-126','E-DIM-SEC','D-C-INJ','依赖',NULL,'责任边界设计中的资料与指令隔离、白名单输出等措施，直接来自间接提示注入研究的风险结论。',NULL,'["S-11","S-26"]','已核实','2026-11-01');
INSERT OR REPLACE INTO relations (id,source_node_id,target_node_id,relation_type,coverage,description,reasoning_chain,source_ids,evidence_status,checked_at) VALUES ('R-127','E-DIM-SEC','D-RQ-08','依赖',NULL,'本项目的责任边界设计对应培养方案毕业要求 8（负责任人工智能与科技伦理）的透明性、隐私保护与安全性要求。',NULL,'["S-25","S-26"]','已核实','2026-11-01');
INSERT OR REPLACE INTO relations (id,source_node_id,target_node_id,relation_type,coverage,description,reasoning_chain,source_ids,evidence_status,checked_at) VALUES ('R-128','E-DIM-FEISHU','D-T-NODESQLITE','alternative_to',NULL,'飞书多维表格与自建 SQLite 是两种数据存储选择；本项目因公开访问与凭据管理约束无法核实而选择后者，并保留数据可迁出通道。',NULL,'["S-21","S-22","S-26"]','已核实','2026-11-01');
INSERT OR REPLACE INTO relations (id,source_node_id,target_node_id,relation_type,coverage,description,reasoning_chain,source_ids,evidence_status,checked_at) VALUES ('R-129','E-DIM-FEISHU','E-DIM-SEC','质疑',NULL,'低代码平台把数据托管在厂商体系内、公开访问依赖账号与分享设置，与课程「无需逐人申请权限」要求存在张力，是必须核实的合规点。','课程要求匿名可访问且无需申请权限 -> 平台型工具的公开访问通常依赖账号体系与分享设置 -> 本次研究无法核实妙搭的匿名公开访问能力 -> 因此该张力构成对平台选型的实质质疑（结论限定为「无法核实」，不断言平台不满足）。','["S-21","S-22","S-24"]','推断','2026-11-01');
INSERT OR REPLACE INTO relations (id,source_node_id,target_node_id,relation_type,coverage,description,reasoning_chain,source_ids,evidence_status,checked_at) VALUES ('R-130','E-DIM-INTL','E-PA-FLARE','based_on',NULL,'FLARE 的作者机构同时包含中国高校（北航）、美国高校（CMU）与产业实验室（Sea AI Lab），是跨国合作的具体实例。',NULL,'["S-13"]','部分核实','2026-11-01');
INSERT OR REPLACE INTO relations (id,source_node_id,target_node_id,relation_type,coverage,description,reasoning_chain,source_ids,evidence_status,checked_at) VALUES ('R-131','E-DIM-INTL','D-M-GLM46','质疑',NULL,'智谱官方称 GLM-4.6 代码能力「对齐 Claude Sonnet 4」，属厂商以国际头部模型为参照的自评表述，需独立评测佐证。','厂商自述能力对标国际头部模型 -> 自评数据虽公开了测试轨迹但仍含商业立场 -> 学术界（HELM）提供独立评测框架 -> 因此对厂商自评应保持「官方称」的标注距离（本项目据此不作为独立核实结论）。','["S-16"]','推断','2026-11-01');
INSERT OR REPLACE INTO relations (id,source_node_id,target_node_id,relation_type,coverage,description,reasoning_chain,source_ids,evidence_status,checked_at) VALUES ('R-132','E-DIM-INTL','E-OR-STANFORD','complements',NULL,'Stanford CRFM 的独立评测与厂商自评构成互补，共同支撑「谁在评价模型」这一问题。',NULL,'["S-06","S-16","S-39"]','已核实','2026-11-01');
INSERT OR REPLACE INTO relations (id,source_node_id,target_node_id,relation_type,coverage,description,reasoning_chain,source_ids,evidence_status,checked_at) VALUES ('R-133','D-RQ-03','D-C-RAG','requires_knowledge',NULL,'毕业要求 3 明确列出「生成模型」与「决策与智能体」，RAG 是生成模型应用层的核心方法。',NULL,'["S-25"]','已核实','2026-11-01');
