INSERT OR REPLACE INTO relations (id,source_node_id,target_node_id,relation_type,coverage,description,reasoning_chain,source_ids,evidence_status,checked_at) VALUES ('R-233','C-M-THIRD','C-M-SYSTEM','complements',NULL,'证据观回答「我凭什么这么说」，补足系统观与发展观不直接处理的依据问题（本项目自定义框架）。','课程明确要求系统观与发展观 -> 二者分别处理结构与演化，但不直接约束结论的依据强度 -> LLM 应用领域中流畅语言易被误当作事实 -> 因此本项目补充证据观作为第三个认识方法（明确标注为项目自定义框架，非教师原话）。','["S-24","S-26"]','推断','2026-11-01');
INSERT OR REPLACE INTO relations (id,source_node_id,target_node_id,relation_type,coverage,description,reasoning_chain,source_ids,evidence_status,checked_at) VALUES ('R-234','E-US-TEAM','E-ORG-TEAMSTRUCT','采用',NULL,'本小组采用「模块负责到人 + 工作量均衡 + 交叉评审」的组织方式；4 人各牵头一个技术大模块与一块地图内容。','分工细则 V1.1 由小组编制并列出四人角色与牵头模块 -> 该细则即本组的组织方式 -> 故 E-US-TEAM（本组成员）采用 E-ORG-TEAMSTRUCT（分工结构）。签字确认未完成，标部分核实。','["S-44"]','部分核实','2026-11-01');
INSERT OR REPLACE INTO relations (id,source_node_id,target_node_id,relation_type,coverage,description,reasoning_chain,source_ids,evidence_status,checked_at) VALUES ('R-235','E-ORG-TEAMSTRUCT','E-DIM-SEC','based_on',NULL,'分工细则中的「密钥纪律」与「质量与学术诚信约定 6 条」以本站规则与责任设计为依据（密钥只存服务端、待核实标注、禁止预填分数等）。',NULL,'["S-44","S-26"]','已核实','2026-11-01');
